const spokenLabel=v=>spokenLanguages(v).join(', ')||'Not recorded';
const app=document.querySelector('#app');
const dialog=document.querySelector('#detail');
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2M8 14h2M14 14h2M8 18h2',flag:'M4 22V3M4 4c5-5 11 5 16 0v10c-5 5-11-5-16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',report:'M14 2H4v20h16V8l-6-6v6h6M8 13h8M8 17h6',arrow:'M5 12h14M13 6l6 6-6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',out:'M9 4H4v16h5M10 12h12M17 7l5 5-5 5',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const brand=()=>'<a class="brand" href="#overview" aria-label="TidePath Family Alliance"><img src="/icon.svg" alt=""><span>TidePath<small>Family Alliance</small></span></a>';
const name=s=>`${s.first_name} ${s.last_name}`;
const initials=label=>label.split(' ').map(w=>w[0]).slice(0,2).join('');
const day=d=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const titleCase=s=>s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const badge=(label,style='')=>`<span class="badge ${style}">${E(label)}</span>`;
const statusBadge=status=>badge(status==='draft'?'Not submitted':titleCase(status),status==='draft'?'warning':status==='submitted'||status==='resolved'||status==='approved'?'success':status==='awaiting_reply'?'blue':'');
const person=s=>`<div class="person"><span class="avatar" aria-hidden="true">${E(initials(name(s)))}</span><button class="name-button" data-action="student" data-id="${E(s.id||s.student_id)}">${E(name(s))}</button></div>`;
let state=null,me=null,roster=null,marks={},dirty=false,search='',programFilter='',sessionFilter='all',taskFilter='active',hoursFilter='pending',volunteerTab='hours',registerLocale='English',reportDraft=null;
let noticeTimer,registrationRequestHash='',familyDraft=null,assessmentDetail=null,intakePreview=null,intakeCSV='',quarterReview=null,savedSnapshot=null,adminData=null,manageTab='programs',installPrompt=null;
async function api(path,options={}){let response;try{response=await fetch('/api'+path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});}catch{throw new Error('Connection lost. Reconnect before saving. Your current entries are still on this screen.');}const data=await response.json();if(!response.ok){if(response.status===401&&state){state=null;me=null;renderLogin();}throw new Error(data.error||'The request failed.');}return data;}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
const put=(path,data)=>api(path,{method:'PUT',body:JSON.stringify(data)});
function notify(message){const n=document.querySelector('#notice');n.textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.textContent='',6000);}
function error(message){const target=dialog.open?dialog.querySelector('.error-text'):document.querySelector('#page-error');if(target){target.textContent=message;target.setAttribute('role','alert');}else notify(message);}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function btn(label,action,iconName='',primary=false,extra=''){return `<button class="btn${primary?' primary':''}" data-action="${action}" ${extra}>${iconName?icon(iconName):''}${label}</button>`;}
function empty(title,description,action=''){return `<div class="empty">${icon('check')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function panel(title,description,body,action=''){return `<section class="panel"><header class="panel-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</header>${body}</section>`;}
function shell(content,page){
  const nav=state.user.role==='manager'?[['overview','Overview','home'],['programs','Programs','report'],['participants','Participants','people'],['attendance','Attendance','calendar'],['followups','Follow-ups','flag'],['volunteers','Volunteers','heart'],['reports','Reports','report'],['manage','Manage workspace','people']]:[['attendance','My sessions','calendar']];
  const active=state.followups?.filter(f=>f.status!=='resolved').length||0;
  app.innerHTML=`<div class="offline" ${navigator.onLine?'hidden':''}>You’re offline. Reconnect to load records or save attendance. Offline synchronization is not enabled.</div><div class="app-shell"><aside class="sidebar">${brand()}<p class="workspace-label">Program workspace</p><div class="mobile-brand">${brand()}<button class="icon-button" data-action="logout" aria-label="Sign out">${icon('out')}</button></div><nav class="nav-list" aria-label="Workspace">${nav.map(([id,label,i])=>`<a href="#${id}" class="nav-link ${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${icon(i)}${label}${id==='followups'&&active?`<span class="nav-count">${active}</span>`:''}</a>`).join('')}</nav><button class="btn install-app" data-action="install-app">${icon('download')}Install app</button><div class="sidebar-note"><strong>Every connection counts.</strong><span class="small muted">Little Havana · West Little River</span></div><div class="sidebar-user"><span class="avatar">${E(initials(state.user.name))}</span><div class="user-label"><strong>${E(state.user.name.split(' ')[0])}</strong><div class="small muted">${state.user.role==='manager'?'Program manager':'Session leader'}</div></div><button class="icon-button" data-action="logout" aria-label="Sign out">${icon('out')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Program workspace <span>/</span><strong>${nav.find(n=>n[0]===page)?.[1]||(page==='import'?'CSV import':page==='quarter-close'?'Quarter close':'Registration')}</strong></div><div class="demo-pill"><span class="demo-dot"></span>${state.demo?'Fictional demo':'Program workspace'} · ${E(state.config.quarter_start)}–${E(state.config.quarter_end)}</div></header><main class="content" id="main" data-page="${E(page)}">${content}${content.includes('id="page-error"')?'':'<p class="error-text" id="page-error" role="alert"></p>'}</main><footer class="shell-footer"><span>${E(state.workspace?.organization_name||'Tidepath Family Alliance')}</span><span>Working date: ${E(state.config.demo_today)} · ${state.demo?'All people and records are fictional':'Program coordination workspace'}</span></footer></div></div>`;
}
function stats(){const t=state.report.totals;return `<div class="stats"><button class="stat" data-action="evidence" data-kind="students"><span class="stat-label">${icon('people')}Unique participants</span><strong class="number">${t.students}</strong><small>${t.program_enrollments} program enrollments</small></button><button class="stat" data-action="evidence" data-kind="attendance"><span class="stat-label">${icon('calendar')}Regular-session attendance</span><strong class="number">${t.attendance_rate??'—'}${t.attendance_rate===null?'':'%'}</strong><small>${t.rate_attended} attended regular sessions</small></button><button class="stat" data-action="navigate" data-page="followups"><span class="stat-label">${icon('flag')}Open follow-ups</span><strong class="number">${t.open_followups}</strong><small class="warn">${state.followups.filter(f=>f.status!=='resolved'&&f.due_date<state.config.demo_today).length} overdue · needs attention</small></button><button class="stat" data-action="navigate" data-page="volunteers"><span class="stat-label">${icon('heart')}Volunteer hours</span><strong class="number">${t.approved_hours}</strong><small>${t.pending_hours} hours awaiting approval</small></button></div>`;}
function sessionItem(s){return `<div class="session-item"><div class="date-box">${new Date(s.date+'T12:00:00Z').toLocaleString('en-US',{month:'short',timeZone:'UTC'})}<strong>${Number(s.date.slice(-2))}</strong></div><div class="session-description"><strong>${E(s.group_name)}</strong><p>${E(s.topic)}</p><div>${statusBadge(s.status)}</div></div><button class="icon-button" data-action="roster" data-id="${E(s.id)}" aria-label="Open ${E(s.group_name)} roster for ${E(s.date)}">${icon('arrow')}</button></div>`;}
function briefContact(f){return `<article class="brief-item"><div><strong>${E(f.first_name)} ${E(f.last_name)}</strong><p class="small muted">${E(f.program_name)} · ${E(f.owner_name)} · Due ${day(f.due_date)}</p><p class="small">${E(f.next_action||f.reason)}</p>${f.overdue?badge('Overdue','warning'):''}</div>${btn('Open follow-up','followup','arrow',false,`data-id="${f.id}"`)}</article>`;}
function briefAttendance(s){return `<article class="brief-item"><div><strong>${E(s.group_name)}</strong><p class="small muted">${day(s.date)} · ${E(s.owner_name)}</p>${s.overdue?badge('Attendance overdue','warning'):badge('Not submitted','blue')}</div><a class="btn small" href="${s.href}">Take attendance</a></article>`;}
function briefAssessment(a){return `<article class="brief-item"><div><strong>${E(a.name)}</strong><p class="small muted">${E(a.program_name)} · ${E(a.owner_name)}</p></div>${btn(a.phase==='start'?'Record start response':'Record end response','new-assessment','',false,`data-id="${a.student_id}" data-program-id="${a.program_id}" data-phase="${a.phase||'end'}"`)}</article>`;}
function overview(){
 const b=state.brief,c=b.counts;
 const last=b.last_check?`Last checked ${new Date(b.last_check.ran_at).toLocaleString('en-US',{timeZone:'America/New_York'})} · ${b.last_check.trigger==='scheduled'?'daily check':'staff check'}`:'The daily in-app check is configured. Run it now to refresh reminders';
 const summary=`<section class="weekly-summary"><p class="eyebrow">${b.demo?'Fictional demo · ':''}${day(b.as_of)}–${day(b.week_end)}, ${b.as_of.slice(0,4)}</p><p class="brief-lead"><strong>${c.families_to_contact}</strong> ${c.families_to_contact===1?'family needs':'families need'} a check-in. <strong>${c.unsubmitted_sessions}</strong> ${c.unsubmitted_sessions===1?'session needs':'sessions need'} attendance (${c.overdue_sessions} overdue). <strong>${c.overdue_followups}</strong> ${c.overdue_followups===1?'follow-up is':'follow-ups are'} overdue.</p><p class="small">${E(last)}. Reminders stay inside TidePath; no messages are sent.</p></section>`;
 const contacts=panel('Families to reach',`${c.followups} open concerns due by ${day(b.week_end)} · each has a staff owner`,b.contacts.length?`<div class="panel-body">${b.contacts.map(briefContact).join('')}</div>`:empty('No family check-ins due','New concerns appear when attendance is submitted or staff create a task.'));
 const attendance=panel('Attendance to finish',`${c.unsubmitted_sessions} sessions through ${day(b.week_end)} · missing attendance can hide a concern`,b.attendance.length?`<div class="panel-body">${b.attendance.map(briefAttendance).join('')}</div>`:empty('Attendance is up to date','Every scheduled session in this window has been submitted.'));
 const assessments=panel('Finish the outcome picture',`${c.missing_starts} start and ${c.missing_ends} end responses missing · voluntary program feedback`,b.missing_assessments.length?`<div class="panel-body">${b.missing_assessments.map(briefAssessment).join('')}</div>`:empty('Responses are accounted for','All recorded starts have a corresponding end response.'));
 const contributions=panel('Contributions awaiting review',`${c.pending_hour_entries} entries · ${c.pending_hours} volunteer hours · ${E(b.manager.name)}`,`<div class="panel-body"><p>Only approved contributions enter the approved-hours total. Review each entry or disclose it when saving the quarter report.</p><div class="form-actions">${btn('Review volunteer hours','review-hours','arrow')}</div></div>`);
 shell(heading(`${E(state.user.name.split(' ')[0])}, here’s your week.`,'The people and unfinished work that need your attention, with a next action for each.',`${btn('Run weekly check','run-weekly-check','check')}<a class="btn primary" href="#quarter-close">Close the quarter ${icon('arrow')}</a>`)+summary+`<div class="brief-grid">${contacts}${attendance}${assessments}${contributions}</div><h2 class="registration-section-title">Your programs at a glance</h2>`+stats(),'overview');
}
const snapshotStatus=s=>({provisional:'Provisional snapshot',issued:'Issued report',issued_with_gaps:'Issued with disclosed gaps'}[s]||s);
async function closeQuarter(snapshotId=''){
 if(snapshotId){savedSnapshot=await api('/quarter/snapshots/'+encodeURIComponent(snapshotId));renderSnapshot();return;}
 const [preview,archive]=await Promise.all([api('/quarter/close'),api('/quarter/snapshots')]);quarterReview=preview;savedSnapshot=null;
 const r=preview.report,q=preview.readiness,g=q.gaps;
 const checklist=panel('1. Finish or disclose outstanding work','Open the source record directly. You can save a snapshot with gaps if you explain them.',`<div class="panel-body"><details class="close-check" open><summary>Attendance · ${g.unsubmitted_sessions} unsubmitted sessions</summary>${q.unsubmitted.length?q.unsubmitted.map(s=>`<article class="brief-item"><div><strong>${E(s.group_name)}</strong><p class="small muted">${day(s.date)} · ${s.unmarked} not recorded</p></div><a class="btn small" href="#attendance?session=${encodeURIComponent(s.id)}">Take attendance</a></article>`).join(''):'<p>All session attendance is submitted.</p>'}</details><details class="close-check"><summary>Volunteer contributions · ${g.pending_hour_entries} pending entries</summary><p>${r.totals.pending_hours} hours are not yet included in approved totals.</p>${btn('Review volunteer hours','review-hours','arrow')}</details><details class="close-check"><summary>Program feedback · ${g.missing_assessments} responses missing</summary>${q.missing_assessments.length?q.missing_assessments.map(briefAssessment).join(''):'<p>All recorded starts have an end response.</p>'}</details><details class="close-check"><summary>Family follow-through · ${g.open_followups} open concerns due by quarter end</summary>${q.open_followups.map(briefContact).join('')||'<p>No open concerns due in this period.</p>'}</details></div>`);
 const form=panel('2. Review and save a dated version',q.period_complete?'The saved report and its evidence will remain unchanged.':'The quarter is still in progress. Saving now creates a provisional snapshot.',`<div class="panel-body"><form id="quarter-close-form"><input type="hidden" name="expected" value="${preview.fingerprint}"><p><strong>${r.totals.students} children · ${r.totals.attendance_rate??'—'}% regular attendance · ${r.totals.approved_hours} approved volunteer hours · ${r.totals.assessment_pairs} paired responses</strong></p><div class="field"><label for="quarter-notes">${q.gap_count?'Explain the unresolved gaps':'Staff notes (optional)'}</label><textarea id="quarter-notes" name="notes" rows="4" maxlength="3000" ${q.gap_count?'required':''} placeholder="Explain incomplete data and any work that will continue after this version is saved."></textarea></div><label class="check-row"><input id="quarter-reviewed" name="reviewed" type="checkbox" required><span>I reviewed the figures and disclosed gaps. I understand this saves a report version; it does not mark unfinished work complete.</span></label><div class="form-actions"><button class="btn primary" type="submit">${q.period_complete?'Save quarter report':'Save provisional snapshot'}</button></div><p class="small muted">Saved versions cannot be edited or deleted through the app. Later corrections belong in a new version. The narrative uses verified figures; no AI call is required.</p></form></div>`);
 const history=panel('Saved report versions',`${archive.snapshots.length} dated versions`,archive.snapshots.length?`<div class="table-wrap"><table><thead><tr><th>Period</th><th>Version</th><th>Saved</th><th>Open</th></tr></thead><tbody>${archive.snapshots.map(s=>`<tr><td>${E(s.quarter_start)}–${E(s.quarter_end)}</td><td>${badge(snapshotStatus(s.status),s.status==='issued'?'success':'warning')}</td><td>${E(new Date(s.created_at).toLocaleString('en-US',{timeZone:'America/New_York'}))}</td><td><a href="#quarter-close?snapshot=${encodeURIComponent(s.id)}">Open saved report</a></td></tr>`).join('')}</tbody></table></div>`:empty('No saved versions yet','Save the reviewed report to keep its numbers and evidence together.'));
 shell(heading('Close the quarter.',`${r.start}–${r.end} · ${q.period_complete?'Quarter end reached':'Quarter in progress'} · As of ${q.as_of}`,`<a class="btn" href="#reports">Live report</a>${btn('Refresh checklist','refresh-quarter','check')}`)+(!q.period_complete?`<div class="callout info"><div>${icon('info')}</div><div><strong>Quarter end is ${day(r.end)}.</strong><p>The demo is currently on ${day(q.as_of)}. A snapshot saved now stays provisional, even if all records are complete.</p></div></div>`:'')+`<div class="stack">${checklist}${form}${history}</div>`,'quarter-close');
}
function renderSnapshot(){const s=savedSnapshot,r=s.report,t=r.totals;
 const metrics=[['Children',t.students,'students'],['Recorded visits',t.attended,'attendance'],['Approved hours',t.approved_hours,'hours'],['Paired responses',t.assessment_pairs,'pairs']];
 shell(heading(snapshotStatus(s.status),`${r.start}–${r.end} · Saved ${new Date(s.saved_at).toLocaleString('en-US',{timeZone:'America/New_York'})} by ${s.saved_by.name}`,`<a class="btn" href="#quarter-close">Saved versions</a>${btn('Download evidence','download-snapshot','download')}${btn('Print / PDF','print','report')}`)+`<div class="callout info"><div>${icon('info')}</div><div><strong>This is a saved report version.</strong><p>Figures, source records and disclosures are frozen as of ${E(s.as_of)}. Changes to live attendance, hours or assessments will not change this version.</p></div></div><div class="report-grid snapshot-metrics">${metrics.map(([label,value,kind])=>`<button class="report-metric" data-action="snapshot-evidence" data-kind="${kind}"><span>${label}</span><strong class="number">${value}</strong><small>Saved evidence ${icon('arrow')}</small></button>`).join('')}</div>`+panel('Quarter report','Verified figures and definitions saved together',`<div class="panel-body"><div class="report-text">${E(s.narrative)}</div></div>`)+panel('Staff disclosure','Saved with this version',`<div class="panel-body report-text">${E(s.notes||'No additional staff notes. No unresolved checklist gaps were recorded.')}</div>`),'quarter-close');document.querySelector('#main').scrollIntoView({block:'start'});
}

const programVisuals={harbor:{image:'program-harbor.jpg',tone:'orange'},compass:{image:'program-compass.jpg',tone:'slate'},nextwave:{image:'program-nextwave.jpg',tone:'sky'},brightminds:{image:'program-bright.jpg',tone:'sun'},together:{image:'band.jpg',tone:'orange'}};
function programsPage(){
  const content=heading('Programs that meet families where they are.','Explore the programs, the people they serve, and the records that support them.',`<a class="btn" href="#manage">Manage programs and groups</a>`)+
    `<div class="program-catalog">${state.programs.map((p,index)=>{
      const visual=programVisuals[p.id]||{image:'band.jpg',tone:'slate'};
      const d=JSON.parse(p.details),groups=state.groups.filter(g=>g.program_id===p.id),count=state.report.programs.find(r=>r.id===p.id)?.students||0;
      return `<section class="panel program-card program-tone-${visual.tone}"><figure class="program-photo"><img src="/assets/${visual.image}" alt="Illustrative photo for ${E(p.name)}" loading="lazy" width="900" height="506"><span class="program-index" aria-hidden="true">${String(index+1).padStart(2,'0')}</span></figure><header class="panel-head"><div>${p.active===0?badge('Archived','warning'):''}${badge(p.category,d.enrollment_mode==='secure_system'?'blue':'success')}<h2 style="margin-top:12px">${E(p.name)}</h2><p>${E(d.tagline)}</p></div></header><div class="panel-body"><p class="program-description">${E(p.description)}</p><dl class="program-facts"><div><dt>Who it serves</dt><dd>${E(d.audience||`Ages ${p.min_age}–${p.max_age}`)}</dd></div><div><dt>When</dt><dd>${E(d.schedule||'See group schedule')}</dd></div><div><dt>Where</dt><dd>${d.locations.map(E).join('<br>')}</dd></div><div><dt>Demo participation</dt><dd>${d.enrollment_mode==='secure_system'?'Catalog only · no client records':`${count} students · ${groups.length} ${groups.length===1?'group':'groups'}`}</dd></div></dl><button class="btn" data-action="program" data-id="${p.id}" aria-label="Explore ${E(p.name)}">Explore program ${icon('arrow')}</button></div></section>`;
    }).join('')}</div>`;
  shell(content,'programs');
}
function programDetail(id){
  const p=state.programs.find(p=>p.id===id),d=JSON.parse(p.details),groups=state.groups.filter(g=>g.program_id===id);
  const list=items=>`<ul>${items.map(item=>`<li>${E(item)}</li>`).join('')}</ul>`;
  showDialog(p.name,`<figure class="detail-photo"><img src="/assets/${(programVisuals[p.id]||{image:'band.jpg'}).image}" alt="Illustrative photo for ${E(p.name)}" width="900" height="506"></figure>${badge(p.category,'success')}<p class="program-description">${E(p.description)}</p><dl class="program-facts"><div><dt>Audience</dt><dd>${E(d.audience||`Ages ${p.min_age}–${p.max_age}`)}</dd></div><div><dt>Format</dt><dd>${E(d.format)}</dd></div><div><dt>Schedule</dt><dd>${E(d.schedule||'See group schedule')}</dd></div><div><dt>Locations</dt><dd>${d.locations.map(E).join('<br>')}</dd></div><div><dt>Languages</dt><dd>${d.languages.map(E).join(' · ')}</dd></div><div><dt>Program lead</dt><dd>${E(d.lead)}</dd></div><div><dt>Staffing</dt><dd>${E(d.staffing)}</dd></div><div><dt>Capacity</dt><dd>${E(d.capacity)}</dd></div><div><dt>How families join</dt><dd>${E(d.access)}</dd></div><div><dt>Follow-through</dt><dd>${E(d.followup)}</dd></div></dl><h3>What participants do</h3>${list(d.activities)}<h3>What we measure</h3>${list(d.measures)}<div class="callout info" style="margin-top:24px"><div>${icon('info')}</div><div><strong>Records and reporting</strong><p>${E(d.record_scope)}</p></div></div>${groups.length?`<h3>Demo groups</h3><div class="timeline">${groups.map(g=>`<div class="timeline-entry"><strong>${E(g.name)}</strong><p class="small muted">${E(g.school)} · ${E(g.weekday)} · ${E(g.time)}</p></div>`).join('')}</div>`:''}`);
}
function participants(){
  const filtered=state.students.filter(s=>name(s).toLowerCase().includes(search.toLowerCase())&&(!programFilter||state.enrollments.some(e=>e.student_id===s.id&&e.program_id===programFilter)));
  const content=heading('Participants','One record per child. Connected families, programs, mentors, and attendance.',`<a class="btn primary" href="#register">${icon('plus')}Register a participant</a><a class="btn" href="#import">Import CSV</a>`)+`<div class="toolbar"><div class="search"><label for="participant-search">Find a participant</label><input id="participant-search" type="search" placeholder="Search by name" value="${E(search)}"></div><div><label for="program-filter">Program</label><select id="program-filter"><option value="">All programs</option>${state.programs.map(p=>`<option value="${p.id}" ${programFilter===p.id?'selected':''}>${E(p.name)}</option>`).join('')}</select></div></div>`+panel(`${filtered.length} participants`,`${state.households.length} fictional households in the workspace`,filtered.length?`<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Programs</th><th>Guardian · language</th><th>Mentor</th></tr></thead><tbody>${filtered.map(s=>{const guardian=state.guardians.find(g=>state.links.some(l=>l.student_id===s.id&&l.guardian_id===g.id));const programs=state.programs.filter(p=>state.enrollments.some(e=>e.student_id===s.id&&e.program_id===p.id));const match={volunteer_name:state.matches.filter(m=>m.student_id===s.id&&!m.end_date).map(m=>m.volunteer_name).join(', ')};return `<tr><td>${person(s)}<span class="sub">Age ${s.age}</span></td><td>${programs.map(p=>badge(p.name,p.id==='harbor'?'success':'blue')).join(' ')}</td><td>${E(guardian?.name||'Needs review')}<span class="sub">${E(guardian?.preferred_language||'Not recorded')}</span></td><td>${E(match?.volunteer_name||'—')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching participants','Try another name or select all programs.'),'');
  shell(content,'participants');
}
async function studentDetail(id){const detail=await api('/students/'+encodeURIComponent(id)),s=detail.student;
  const ens=state.enrollments.filter(e=>e.student_id===id),match={volunteer_name:state.matches.filter(m=>m.student_id===id&&!m.end_date).map(m=>m.volunteer_name).join(', ')};
  showDialog(name(s),`<dl class="detail-grid"><div><dt>Age</dt><dd>${s.age}</dd></div><div><dt>Mentor</dt><dd>${E(match?.volunteer_name||'No active mentor')}</dd></div>${detail.guardians.map(g=>`<div><dt>Guardian · ${E(g.preferred_language)}</dt><dd>${E(g.name)}<br><a href="mailto:${E(g.email)}">${E(g.email)}</a><br>${E(g.phone)}<br>${btn('Edit contact details','edit-guardian','',false,`data-id="${g.id}" data-student-id="${id}" aria-label="Edit contact details for ${E(g.name)}"`)}</dd></div>`).join('')}</dl><h3>Program and school history</h3><div class="timeline">${ens.map(e=>`<div class="timeline-entry"><strong>${E(e.group_name)}</strong><p class="small muted">${E(e.school)} · ${day(e.start_date)} – ${e.end_date?day(e.end_date):'current'}</p></div>`).join('')}</div><h3 style="margin-top:24px">Why a follow-up?</h3><p class="small muted">Automatic alerts require two consecutive unexplained absences in the same regular program. You can create a check-in for another concern at any time.</p><div class="explanation-list">${detail.followup_explanation.map(p=>`<article><strong>${E(p.program_name)}</strong><p>${E(p.reason)}</p>${p.latest.length?`<p class="small muted">Latest submitted: ${p.latest.map(r=>`${day(r.date)} — ${titleCase(r.status)}`).join(' · ')}</p>`:''}${p.unsubmitted_dates.length?`<p class="small muted">Attendance not submitted: ${p.unsubmitted_dates.map(day).join(', ')}. These sessions do not count yet.</p>`:''}${p.active_task_id?btn('Open follow-up','followup','arrow',false,`data-id="${p.active_task_id}"`):''}</article>`).join('')}</div><div class="actions">${btn('Create a follow-up','new-followup','plus',false,`data-id="${id}"`)}${btn('Record assessment','new-assessment','plus',false,`data-id="${id}"`)}</div><h3 style="margin-top:24px">Program self-assessments</h3><p class="small muted">Voluntary, non-clinical feedback on a 1–5 scale. Missing responses stay missing.</p>${detail.assessments.length?`<div class="table-wrap"><table><thead><tr><th>Program</th><th>Phase</th><th>Score</th><th>Date</th></tr></thead><tbody>${detail.assessments.map(a=>`<tr><td>${E(a.program_name)}</td><td>${E(titleCase(a.phase))}</td><td>${a.score}/5</td><td>${day(a.recorded_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No assessments recorded.</p>'}<h3 style="margin-top:24px">Attendance history</h3><div class="table-wrap"><table><thead><tr><th>Session</th><th>Attendance</th></tr></thead><tbody>${detail.attendance.map(a=>`<tr><td>${day(a.date)} · ${E(a.group_name)}<span class="sub">${E(a.school)}</span></td><td>${a.session_status==='cancelled'?badge('Cancelled'):a.session_status==='draft'?badge(a.status?`${titleCase(a.status)} · not submitted`:'Not recorded','warning'):badge(titleCase(a.status),['present','late'].includes(a.status)?'success':a.status==='absent'?'warning':'')}</td></tr>`).join('')}</tbody></table></div>`);
}
function attendance(){
  let sessions=state.sessions.filter(s=>(!programFilter||s.group_id===programFilter)&&(sessionFilter==='all'||s.status===sessionFilter));
  const controls=`<div class="toolbar"><div><label for="group-filter">Class or group</label><select id="group-filter"><option value="">All assigned groups</option>${state.groups.map(g=>`<option value="${g.id}" ${programFilter===g.id?'selected':''}>${E(g.name)}</option>`).join('')}</select></div><div class="pill-tabs" aria-label="Session status">${[['all','All sessions'],['draft','Not submitted'],['submitted','Submitted'],['cancelled','Cancelled']].map(([v,l])=>`<button class="${sessionFilter===v?'active':''}" data-action="session-filter" data-value="${v}" aria-pressed="${sessionFilter===v}">${l}</button>`).join('')}</div></div>`;
  shell(heading(state.user.role==='manager'?'Attendance':'Your sessions','Mark every student, then submit attendance. Follow-ups and report totals update immediately; no review is needed.')+controls+panel(`${sessions.length} sessions`,`${day(state.config.quarter_start)} – ${day(state.config.quarter_end)}`,sessions.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Session</th><th>Participants</th><th>Status</th><th>Action</th></tr></thead><tbody>${sessions.map(s=>`<tr><td class="number">${day(s.date)}</td><td><strong>${E(s.group_name)}</strong><span class="sub">${E(s.topic)} · ${E(s.time)}</span></td><td>${s.roster_count} students<span class="sub">${s.status==='cancelled'?'Not counted':s.status==='draft'?`${s.unmarked} not recorded`:`${s.attended} present or late`}</span></td><td>${statusBadge(s.status)}</td><td><button class="btn small" data-action="roster" data-id="${s.id}">${s.status==='draft'?'Take attendance':'View attendance'} ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No sessions in this view','Choose a different group or session status.')),'attendance');
}
async function openRoster(id){roster=await api('/sessions/'+encodeURIComponent(id));marks=Object.fromEntries(roster.roster.map(r=>[r.student_id,r.status]));dirty=false;renderRoster();}
function renderRoster(){
  const {session:s,roster:students}=roster,optionalEvent=JSON.parse(state.programs.find(p=>p.id===s.program_id).details).attendance_rule==='optional',unmarked=Object.values(marks).filter(v=>v===null).length;
  const content=heading(E(s.group_name),`${day(s.date)}, ${s.date.slice(0,4)} · ${E(s.time)} · ${E(s.school)}`,`<a class="btn" href="#attendance">Back to sessions</a>`)+`<div class="callout ${s.status==='cancelled'?'':'info'}"><div>${icon('info')}</div><div><strong>${s.status==='cancelled'?'This session was cancelled.':optionalEvent?'Optional family event.':'Mark everyone, then submit.'}</strong><p>${s.status==='cancelled'?'This session is excluded from attendance rates and absence alerts.':optionalEvent?'Record child check-ins. Optional event nonattendance creates no missed-session task and is excluded from regular-session attendance rates.':'Choose a status for every student and click Submit attendance. This saves attendance and immediately checks for follow-ups after two consecutive unexplained absences in the same program. No manager review is needed.'}</p></div></div>`+panel(E(s.topic),`${students.length} students · ${s.status==='submitted'?'Attendance submitted. Corrections take effect immediately when submitted.':'Submit once everyone has a status. No review or approval step.'}`,`<div class="table-wrap"><table class="roster-table"><thead><tr><th>Participant</th><th>Attendance</th></tr></thead><tbody>${students.map(r=>`<tr><td><div class="person"><span class="avatar">${E(initials(name(r)))}</span><div><strong>${E(name(r))}</strong><span class="sub">Age ${r.age}</span></div></div></td><td><div class="roster-status" role="group" aria-label="Attendance for ${E(name(r))}">${[['present','Present'],['late','Late'],['absent','Absent'],['excused','Excused']].map(([v,l])=>`<button data-action="mark" data-id="${r.student_id}" data-value="${v}" aria-pressed="${marks[r.student_id]===v}" ${s.status==='cancelled'?'disabled':''}>${marks[r.student_id]===v?icon('check'):''}${l}</button>`).join('')}<button data-action="mark" data-id="${r.student_id}" data-value="" aria-pressed="${marks[r.student_id]===null}" ${s.status==='cancelled'||s.status==='submitted'?'disabled':''}>Clear</button></div></td></tr>`).join('')}</tbody></table></div>`,s.status!=='cancelled'?btn('Mark remaining present','mark-all','check',false):'')+(s.status!=='cancelled'?`<div class="sticky-actions"><div><strong id="roster-progress">${students.length-unmarked} of ${students.length} recorded</strong><p class="small muted" id="roster-save-state">${dirty?'Unsaved changes':s.status==='submitted'?'Attendance submitted':'Not submitted yet'}</p></div><div class="actions">${btn('Submit attendance','save-roster','check',true)}</div></div>`:'');
  shell(content,'attendance');
}
function updateMarks(){for(const button of document.querySelectorAll('[data-action=mark]')){const value=button.dataset.value||null,chosen=marks[button.dataset.id]===value;button.setAttribute('aria-pressed',String(chosen));button.innerHTML=(chosen&&value?icon('check'):'')+(value?titleCase(value):'Clear');}document.querySelector('#roster-progress').textContent=`${Object.values(marks).filter(v=>v!==null).length} of ${roster.roster.length} recorded`;document.querySelector('#roster-save-state').textContent='Unsaved changes';}
async function saveRoster(){
  await put('/sessions/'+encodeURIComponent(roster.session.id),{version:roster.session.version,entries:Object.entries(marks).map(([student_id,status])=>({student_id,status}))});
  const id=roster.session.id;dirty=false;await refresh(false);await openRoster(id);notify('Attendance submitted. Follow-ups and report totals are updated.');
}
function followups(){
  const tasks=state.followups.filter(f=>taskFilter==='all'||(taskFilter==='active'?f.status!=='resolved':f.status==='resolved'));
  shell(heading('Follow-through, not just reminders.','Every concern has an owner, a due date, and a history. Sending a message does not resolve the task.',btn('Create a follow-up','new-followup','plus',true))+`<div class="toolbar"><div class="pill-tabs">${[['active','Open follow-ups'],['resolved','Resolved'],['all','All']].map(([v,l])=>`<button data-action="task-filter" data-value="${v}" class="${v===taskFilter?'active':''}">${l}</button>`).join('')}</div><span class="muted small">Working date: ${E(state.config.demo_today)}</span></div><div class="task-list">${tasks.length?tasks.map(f=>`<article class="task-item"><div class="task-top"><div><h2>${E(name(f))}</h2><span class="small muted">${E(f.program_name)} · ${E(f.owner_name)}</span></div><div class="actions">${statusBadge(f.status)}${f.status!=='resolved'&&f.due_date<state.config.demo_today?badge('Overdue','warning'):''}</div></div><p>${E(f.reason)}</p><p><strong>Next action:</strong> ${E(f.next_action)}</p><div class="actions"><span class="small muted">Due ${day(f.due_date)}</span><button class="btn small" data-action="followup" data-id="${f.id}">Open follow-up ${icon('arrow')}</button></div></article>`).join(''):empty('No follow-ups in this view','Submitted attendance triggers a task after two consecutive unexplained absences.')}</div>`,'followups');
}
async function followupDetail(id){
  const {task:t,events,guardians}=await api('/followups/'+encodeURIComponent(id));
  showDialog(`Follow-up · ${name(t)}`,`<div class="row-between">${statusBadge(t.status)}<span class="small muted">${E(t.program_name)}</span></div><p style="margin-top:16px">${E(t.reason)}</p><p class="small muted" style="margin-top:8px">${guardians.map(g=>`${E(g.name)} · ${E(g.preferred_language)} · ${E(g.email)}`).join('<br>')}</p><form id="task-form" data-id="${E(id)}" style="margin-top:24px"><div class="form-grid"><div class="field"><label for="task-owner">Owner</label><select id="task-owner" name="owner_id">${state.staff.filter(s=>s.active!==0).map(s=>`<option value="${s.id}" ${s.id===t.owner_id?'selected':''}>${E(s.name)}</option>`).join('')}</select></div><div class="field"><label for="task-due">Due date</label><input id="task-due" name="due_date" type="date" value="${t.due_date}" required></div><div class="field full"><label for="task-next">Next action</label><textarea id="task-next" name="next_action" maxlength="1000" required>${E(t.next_action)}</textarea></div></div><div class="form-actions"><button class="btn" type="submit">Save next step</button></div></form>${t.status!=='resolved'?`<div class="draft-area"><div class="row-between"><h3>Guardian check-in</h3><button class="btn small" data-action="draft-followup" data-id="${id}">${icon('spark')}Draft message</button></div><p class="small muted" id="draft-source">${t.draft_source?E(t.draft_source)+' draft · review before use':'Uses attendance and this contact history. No counseling records.'}</p><label for="contact-draft" style="margin-top:12px">Message draft</label><textarea id="contact-draft" rows="5" placeholder="Draft a message, then review and edit it.">${E(t.draft)}</textarea><div class="form-actions"><button class="btn" data-action="simulate-send" data-id="${id}">Record simulated send</button></div><p class="small muted">Demo only. No email, SMS, or WhatsApp message is sent.</p></div><form id="contact-form" data-id="${id}" style="margin-top:24px"><div class="field"><label for="contact-kind">Record an update</label><select name="kind" id="contact-kind"><option value="reply">Guardian reply</option><option value="note">Staff note</option><option value="resolution">Resolve with an explanation</option></select></div><div class="field" style="margin-top:12px"><label for="contact-body">What happened?</label><textarea name="body" id="contact-body" required maxlength="4000" placeholder="Record the reply, support arranged, or reason for resolution."></textarea><span class="hint">Program coordination only. Keep counseling notes in the secure counseling system.</span></div><div class="form-actions"><button class="btn primary" type="submit">Save update</button></div></form>`:''}<h3 style="margin-top:24px">Contact history</h3><div class="timeline">${events.length?events.map(e=>`<div class="timeline-entry"><strong>${E(titleCase(e.kind))}</strong><small> · ${E(e.staff_name)} · ${new Date(e.created_at).toLocaleString()}</small><p>${E(e.body)}</p></div>`).join(''):'<p class="muted" style="padding-top:16px">No contact attempts recorded yet.</p>'}</div>`);
}
function volunteers(){
  const hours=state.hours.filter(h=>hoursFilter==='all'||h.status===hoursFilter);
  const head=heading('The people who show up.','Mentor relationships and volunteer contributions, connected to the sessions they support.',btn('Log volunteer hours','new-hours','plus',true));
  const tabs=`<div class="toolbar"><div class="pill-tabs"><button data-action="volunteer-tab" data-value="hours" class="${volunteerTab==='hours'?'active':''}">Volunteer hours</button><button data-action="volunteer-tab" data-value="mentors" class="${volunteerTab==='mentors'?'active':''}">Mentor matches</button></div>${volunteerTab==='hours'?`<div><label for="hours-filter">Approval status</label><select id="hours-filter">${['pending','approved','rejected','all'].map(v=>`<option value="${v}" ${hoursFilter===v?'selected':''}>${v==='all'?'All entries':titleCase(v)}</option>`).join('')}</select></div>`:btn('Assign a mentor','new-match','plus')}</div>`;
  const content=volunteerTab==='hours'?panel(`${hours.length} hour entries`,`${state.report.totals.approved_hours} approved hours · ${state.report.totals.pending_hours} pending`,hours.length?`<div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Session</th><th>Hours</th><th>Status</th><th>Review</th></tr></thead><tbody>${hours.map(h=>`<tr><td><strong>${E(h.volunteer_name)}</strong></td><td>${E(h.group_name)}<span class="sub">${day(h.date)}</span></td><td class="number">${h.hours}</td><td>${statusBadge(h.status)}</td><td>${h.status==='pending'?`<div class="actions"><button class="btn small" data-action="approve-hours" data-id="${h.id}">${icon('check')}Approve</button><button class="btn link small" data-action="reject-hours" data-id="${h.id}">Reject</button></div>`:badge('Reviewed')}</td></tr>`).join('')}</tbody></table></div>`:empty('No entries in this view','Change the approval filter or log a new contribution.')):panel('Mentor matches','Current and historical assignments across mentoring programs.',`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Program</th><th>Mentor</th><th>From</th><th>Through</th></tr></thead><tbody>${state.matches.map(m=>{const s=state.students.find(s=>s.id===m.student_id);return `<tr><td>${person(s)}</td><td>${E(state.programs.find(p=>p.id===m.program_id)?.name||'Harbor Mentors')}</td><td>${E(m.volunteer_name)}</td><td>${day(m.start_date)}</td><td>${m.end_date?day(m.end_date):badge('Active','success')}</td></tr>`;}).join('')}</tbody></table></div>`);
  shell(head+tabs+content,'volunteers');
}
function hoursForm(){showDialog('Log volunteer hours',`<form id="hours-form"><div class="form-grid"><div class="field"><label for="hours-volunteer">Volunteer</label><select id="hours-volunteer" name="volunteer_id">${state.volunteers.filter(v=>v.active!==0).map(v=>`<option value="${v.id}">${E(v.name)}</option>`).join('')}</select></div><div class="field"><label for="hours-amount">Hours contributed</label><input id="hours-amount" name="hours" type="number" min="0.25" max="24" step="0.25" value="1" required></div><div class="field full"><label for="hours-session">Session</label><select id="hours-session" name="session_id">${state.sessions.filter(s=>s.status!=='cancelled').map(s=>`<option value="${s.id}">${day(s.date)} · ${E(s.group_name)}</option>`).join('')}</select></div><div class="field full"><label for="hours-note">Activity note (optional)</label><input id="hours-note" name="note" maxlength="500"></div></div><p class="small muted" style="margin-top:16px">Entries start pending. Only approved hours enter the quarterly total. A volunteer can have one entry per session.</p><div class="form-actions"><button class="btn primary" type="submit">Submit hours for review</button></div></form>`);}
const isMentoring=p=>Boolean(JSON.parse(p.details).mentor_program??(p.category==='Mentoring'));
function matchForm(){const programs=state.programs.filter(p=>p.active!==0&&isMentoring(p));showDialog('Assign a mentor',`<form id="match-form"><div class="form-grid"><div class="field full"><label for="match-program">Mentoring program</label><select id="match-program" name="program_id" required>${programs.map(p=>`<option value="${p.id}">${E(p.name)}</option>`).join('')}</select></div><div class="field"><label for="match-student">Enrolled participant</label><select id="match-student" name="student_id" required></select></div><div class="field"><label for="match-volunteer">Mentor</label><select id="match-volunteer" name="volunteer_id" required>${state.volunteers.filter(v=>v.role==='Mentor'&&v.active!==0).map(v=>`<option value="${v.id}">${E(v.name)} · ${E(spokenLabel(v))}</option>`).join('')}</select></div></div><p class="small muted">Reassignment ends the prior match in this program and preserves its history.</p><div class="form-actions"><button class="btn primary" type="submit">Save mentor match</button></div></form>`);updateMentorStudents();}
function updateMentorStudents(){const program=document.querySelector('#match-program').value;document.querySelector('#match-student').innerHTML=state.students.filter(s=>state.enrollments.some(e=>e.student_id===s.id&&e.program_id===program&&e.start_date<=state.config.demo_today&&(!e.end_date||e.end_date>=state.config.demo_today))).map(s=>`<option value="${s.id}">${E(name(s))}</option>`).join('');}

function reports(){
  const r=state.report,t=r.totals;
  const metrics=[['Unique participants',t.students,'Count each child once','students'],['Program enrollments',t.program_enrollments,'Distinct child–program pairs','students'],['Recorded visits',t.attended,`${t.attended-t.rate_attended} optional event check-ins included`,'attendance'],['Approved volunteer hours',t.approved_hours,`${t.pending_hours} hours pending review`,'hours'],['Paired self-assessments',t.assessment_pairs,`${t.assessment_missing_end} end assessments missing`,'pairs'],['Unfinished rosters',t.incomplete_sessions,`${t.unmarked} entries not recorded`,'incomplete']];
  shell(heading('A report you can trace.',`${r.start}–${r.end} · Live report${state.demo?' · Fictional demonstration':''}`,`<a class="btn primary" href="#quarter-close">Close the quarter</a>${btn('Record assessment','new-assessment','plus')}${btn('Download evidence','download-report','download')}${btn('Print / save PDF','print','report')}`)+`<div class="callout"><div>${icon('info')}</div><div><strong>Provisional until outstanding records are reviewed.</strong><p>${t.incomplete_sessions} unfinished rosters, ${t.pending_hours} pending volunteer hours, and ${t.assessment_missing_end} missing end assessments. Working date: ${E(state.config.demo_today)}. Use Close the quarter to review and save a dated version.</p></div></div><div class="report-grid">${metrics.map(([label,value,sub,kind])=>`<button class="report-metric" data-action="evidence" data-kind="${kind}"><span class="muted">${label}</span><strong class="number">${value}</strong><small>${sub} ${icon('arrow')}</small></button>`).join('')}</div>`+panel('Quarterly narrative','Computed figures come from the database. Draft wording requires staff review.',`<div class="panel-body"><div class="callout info"><div>${icon('spark')}</div><div><strong>${state.ai_available?'Workers AI is available':'Template drafting is available'}</strong><p>The assistant summarizes verified totals. It does not invent outcomes, send communications, or access counseling records.</p></div></div><div id="report-output" class="report-text">${reportDraft?E(reportDraft.text):'Generate a draft to turn this quarter’s verified figures and outstanding issues into a board-ready starting point.'}</div><p class="small muted" id="report-source" style="margin-top:16px">${reportDraft?E(reportDraft.source)+' · '+E(reportDraft.warning||'Review against the evidence before sharing.'):'No narrative generated yet.'}</p></div>`,btn('Draft quarterly narrative','draft-report','spark',true))+`<section class="panel" style="margin-top:24px"><header class="panel-head"><h2>Definitions behind the numbers</h2></header><div class="panel-body"><p><strong>Attendance:</strong> present and late entries divided by present, late, and unexplained absent entries from submitted regular-session rosters. Optional community events, excused absences, cancelled sessions, and unsubmitted attendance are excluded. Event check-ins remain in recorded-visit totals.</p><p style="margin-top:12px"><strong>Assessment change:</strong> ${t.average_gain.toFixed(2)} points on a five-point scale among paired responses. Fictional, descriptive program feedback; not a clinical assessment or proof of causality.</p><p style="margin-top:12px"><strong>Reporting scope:</strong> this report includes ${t.students} participants in the configured reporting period. Donor, grant accounting, and counseling records remain in their existing systems.</p></div></section>`,'reports');
}
function evidence(kind,r=state.report,frozen=false){
  const e=r.evidence;let title,headers,rows;
  if(kind==='students'){title='Unique participants · source records';headers=['Participant','Programs'];rows=e.students.map(s=>[name(s),s.programs]);}
  else if(kind==='attendance'){title='Submitted attendance · source records';headers=['Participant','Session','Date','Status'];rows=e.attendance.map(a=>[a.name,a.group_name,a.date,a.status]);}
  else if(kind==='hours'){title='Volunteer hours · source records';headers=['Volunteer','Session','Hours','Approval'];rows=e.hours.map(h=>[h.volunteer_name,`${h.date} · ${h.group_name}`,h.hours,h.status]);}
  else if(kind==='pairs'){title='Paired self-assessments · fictional';headers=['Student','Program','Start','End','Change'];rows=e.pairs.map(p=>[p.name,r.programs.find(pr=>pr.id===p.program_id)?.name,p.start,p.end,p.gain]);}
  else{title='Incomplete rosters';headers=['Session','Date','Not recorded'];rows=e.incomplete.map(s=>[s.group_name,s.date,s.unmarked]);}
  showDialog(title,`<p class="muted small">${rows.length} source records. ${frozen?'These are the saved source records for this version; they do not change with live records.':'These totals update when records change; use Close the quarter to save a frozen version.'}</p><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${E(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}
