function captureFamily(){
 const form=document.querySelector('#registration-form');if(!form)return;
 const fields=new FormData(form);familyDraft={...familyDraft,...Object.fromEntries(fields),children:[...form.querySelectorAll('.registration-child')].map(card=>({first_name:card.querySelector('[data-child-field="first_name"]').value,last_name:card.querySelector('[data-child-field="last_name"]').value,age:card.querySelector('[data-child-field="age"]').value,group_ids:[...card.querySelectorAll('input[type=checkbox]:checked')].map(input=>input.value)}))};
}
async function registration(){
 const params=new URLSearchParams(location.hash.split('?')[1]||'');
 if(registrationRequestHash!==location.hash){const language=params.get('language');if(translations[language])registerLocale=language;registrationRequestHash=location.hash;familyDraft=null;}
 const base=state||await api('/public/programs'),data={...base,programs:base.programs.filter(p=>p.active!==0),groups:base.groups.filter(g=>g.active!==0&&base.programs.some(p=>p.id===g.program_id&&p.active!==0))},t=translations[registerLocale],f=familyCopy[registerLocale];
 if(!familyDraft){const requestedGroup=params.get('group'),requestedProgram=params.get('program');const initialGroups=data.groups.filter(g=>requestedGroup===g.id||(!requestedGroup&&g.program_id===requestedProgram&&data.groups.filter(item=>item.program_id===g.program_id).length===1)).map(g=>g.id);familyDraft={guardian_name:'',email:'',phone:'',language:registerLocale,neighborhood:data.workspace.service_areas[0],guardian_id:'',children:[{first_name:'',last_name:'',age:'',group_ids:initialGroups}]};}
 const d=familyDraft;
 const field=(id,label,name,value,extra='')=>`<div class="field"><label for="${id}">${E(label)}</label><input id="${id}" name="${name}" value="${E(value)}" ${extra}></div>`;
 const childCards=d.children.map((child,index)=>`<fieldset class="registration-child" data-child-index="${index}"><legend>${E(f.child)} ${index+1}</legend><div class="form-grid">${['first_name','last_name','age'].map((key,i)=>`<div class="field"><label for="child-${index}-${key}">${E([t.child,t.last,t.age][i])}</label><input id="child-${index}-${key}" data-child-field="${key}" value="${E(child[key])}" ${key==='age'?'type="number" min="0" max="18"':'maxlength="80" autocomplete="off"'} required></div>`).join('')}<fieldset class="field full program-choices"><legend>${E(t.programs)}</legend>${data.groups.map(g=>{const p=data.programs.find(p=>p.id===g.program_id);return `<label class="check-row"><input type="checkbox" value="${g.id}" ${child.group_ids.includes(g.id)?'checked':''}><span><strong>${E(g.name)}</strong><br><span class="muted small">${E(g.neighborhood)} · ${E(g.weekday)} · ${E(g.time)} · ${E(t.age)} ${p.min_age}–${p.max_age}</span></span></label>`;}).join('')}<p class="small muted">${E(f.choose)}</p></fieldset></div>${d.children.length>1?`<button class="btn small" type="button" data-action="remove-child" data-id="${index}" aria-label="${E(f.remove)} ${index+1}">${E(f.remove)}</button>`:''}</fieldset>`).join('');
 const form=`<p class="workspace-name">${E(data.workspace.organization_name)}</p><div class="toolbar"><span class="small muted">English · Español · Kreyòl ayisyen</span><div><label for="registration-locale">Form language / Idioma / Lang</label><select id="registration-locale">${Object.keys(translations).map(l=>`<option ${l===registerLocale?'selected':''}>${l}</option>`).join('')}</select></div></div>`+panel(t.title,f.description,`<div class="panel-body"><p class="callout info">${E(data.demo?t.note:registerLocale==='Spanish'?'Ingrese los datos de contacto de la familia. No se enviarán mensajes desde esta aplicación.':registerLocale==='Haitian Creole'?'Antre enfòmasyon kontak fanmi an. Aplikasyon sa a p ap voye mesaj.':'Enter the family’s contact details. This app does not send outbound messages.')}</p><form id="registration-form"><h3 class="registration-section-title">${E(f.guardianSection)}</h3><div class="form-grid">${state?.user.role==='manager'?`<div class="field full"><label for="existing-guardian">Household link (staff only)</label><select id="existing-guardian" name="guardian_id"><option value="">Create a new household · review possible duplicates separately</option>${state.guardians.map(g=>`<option value="${g.id}" ${d.guardian_id===g.id?'selected':''}>${E(g.name)} · ${E(g.email)}</option>`).join('')}</select><span class="hint">Link only when you have confirmed the family’s identity.</span></div>`:''}${field('reg-guardian',t.guardian,'guardian_name',d.guardian_name,'required maxlength="120" autocomplete="name"')}${field('reg-email',t.email,'email',d.email,'type="email" required maxlength="200" autocomplete="email"')}${field('reg-phone',t.phone,'phone',d.phone,'type="tel" maxlength="40" autocomplete="tel"')}<div class="field"><label for="reg-neighborhood">${E(t.neighborhood)}</label><select id="reg-neighborhood" name="neighborhood">${data.workspace.service_areas.map(n=>`<option ${n===d.neighborhood?'selected':''}>${n}</option>`).join('')}</select></div><div class="field full"><label for="reg-language">${E(t.language)}</label><select id="reg-language" name="language">${Object.keys(translations).map(l=>`<option ${l===d.language?'selected':''}>${l}</option>`).join('')}</select></div></div><h3 class="registration-section-title">${E(f.childSection)}</h3><p class="small muted" aria-live="polite">${E(f.count(d.children.length))}</p><div id="registration-children">${childCards}</div><button class="btn" type="button" data-action="add-child" ${d.children.length>=10?'disabled':''}>${icon('plus')}${E(f.add)}</button>${d.children.length>=10?`<p class="small muted">${E(f.limit)}</p>`:''}<p class="small muted counseling-note">${E(f.counseling)}</p><div class="form-actions"><button class="btn primary" type="submit">${E(f.submit)}</button></div><p class="error-text" id="page-error" role="alert"></p></form></div>`);
 if(state)shell(heading('Family registration','One guardian, with individual program choices for every child.')+form,'register');
 else app.innerHTML=`<div class="topbar public-topbar">${brand()}<a class="btn" href="#login">Staff sign in</a></div><main class="content" id="main" data-page="register" style="max-width:800px">${form}</main>`;
}

async function manageWorkspace(){adminData=await api('/admin');renderManage();}
function renderManage(){
 const tabs=[['programs','Programs'],['groups','Groups & sessions'],['staff','Staff & access'],['volunteers','Volunteers & mentors'],['settings','Organization']];
 const edit=(table,id)=>btn('Edit','manage-edit','',false,`data-table="${table}" data-id="${id}"`);
 let content='';
 if(manageTab==='settings'){const c=adminData.config;content=panel('Organization and reporting period','Each nonprofit runs its own workspace. Historical records and saved report versions are retained.',`<div class="panel-body"><form id="workspace-settings-form"><input name="version" type="hidden" value="${Number(c.admin_version||0)}"><div class="form-grid"><div class="field full"><label for="workspace-name">Organization name</label><input id="workspace-name" name="organization_name" value="${E(adminData.workspace.organization_name)}" required maxlength="120"></div><div class="field full"><label for="workspace-areas">Service areas (one per line)</label><textarea id="workspace-areas" name="service_areas" required>${E(adminData.workspace.service_areas.join('\n'))}</textarea></div><div class="field"><label for="workspace-start">Reporting period starts</label><input id="workspace-start" name="quarter_start" type="date" value="${c.quarter_start}" required></div><div class="field"><label for="workspace-end">Reporting period ends</label><input id="workspace-end" name="quarter_end" type="date" value="${c.quarter_end}" required></div><div class="field"><label for="workspace-date">Working / demo date</label><input id="workspace-date" name="demo_today" type="date" value="${c.demo_today}" required></div></div><p class="small muted">Changing the period changes the live report, not saved versions. Service areas apply to new registration/import choices; existing household history is retained.</p><div class="form-actions"><button class="btn primary" type="submit">Save organization settings</button></div></form></div>`);}
 else if(manageTab==='programs')content=panel('Program catalog','Archive programs to stop new enrollment while preserving history.',`<div class="table-wrap"><table><thead><tr><th>Program</th><th>Category / ages</th><th>Status</th><th>Edit</th></tr></thead><tbody>${adminData.programs.map(p=>`<tr><td><strong>${E(p.name)}</strong></td><td>${E(p.category)} · ${p.min_age}–${p.max_age}</td><td>${badge(p.active?'Active':'Archived',p.active?'success':'')}</td><td>${edit('programs',p.id)}</td></tr>`).join('')}</tbody></table></div>`,btn('Add program','manage-edit','plus',true,'data-table="programs"'));
 else if(manageTab==='groups')content=panel('Groups and session planning','A group belongs to one program and venue. Schedule sessions after setting up the group and its staff.',`<div class="table-wrap"><table><thead><tr><th>Group / program</th><th>Venue and schedule</th><th>Capacity</th><th>Status</th><th>Edit</th></tr></thead><tbody>${adminData.groups.map(g=>`<tr><td><strong>${E(g.name)}</strong><span class="sub">${E(adminData.programs.find(p=>p.id===g.program_id)?.name)}</span></td><td>${E(g.school)}<span class="sub">${E(g.neighborhood)} · ${E(g.weekday)} · ${E(g.time)}</span></td><td>${g.capacity}</td><td>${badge(g.active?'Active':'Archived',g.active?'success':'')}</td><td>${edit('groups',g.id)}</td></tr>`).join('')}</tbody></table></div>`,`${btn('Schedule session','schedule-session','calendar')}${btn('Add group','manage-edit','plus',true,'data-table="groups"')}`);
 else if(manageTab==='staff')content=panel('Staff accounts and access','Session leaders see only their assigned groups. Volunteers who need attendance access also need a staff account.',`<div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Role / assignments</th><th>Status</th><th>Edit</th></tr></thead><tbody>${adminData.staff.map(s=>`<tr><td><strong>${E(s.name)}</strong><span class="sub">${E(s.email)}</span></td><td>${s.role==='manager'?'Manager · all groups':'Session leader'}<span class="sub">${s.role==='teacher'?adminData.assignments.filter(a=>a.staff_id===s.id).map(a=>E(adminData.groups.find(g=>g.id===a.group_id)?.name)).join(', ')||'No groups assigned':''}</span></td><td>${badge(s.active?'Active':'Inactive',s.active?'success':'')}</td><td>${edit('staff',s.id)}</td></tr>`).join('')}</tbody></table></div>`,btn('Add staff account','manage-edit','plus',true,'data-table="staff"'));
 else content=panel('Volunteers and mentors','Keep volunteer identity and role separate from staff sign-in access.',`<div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Role</th><th>Languages</th><th>Status</th><th>Edit</th></tr></thead><tbody>${adminData.volunteers.map(v=>`<tr><td><strong>${E(v.name)}</strong><span class="sub">${E(v.email)}</span></td><td>${E(v.role)}</td><td>${E(spokenLabel(v))}</td><td>${badge(v.active?'Active':'Archived',v.active?'success':'')}</td><td>${edit('volunteers',v.id)}</td></tr>`).join('')}</tbody></table></div>`,btn('Add volunteer / mentor','manage-edit','plus',true,'data-table="volunteers"'));
 shell(heading('Manage your workspace.','Set up programs, people, access and the reporting period. Changes are recorded in the staff audit history.')+`<div class="toolbar"><div class="pill-tabs manage-tabs">${tabs.map(([value,label])=>`<button data-action="manage-tab" data-value="${value}" class="${manageTab===value?'active':''}" aria-pressed="${manageTab===value}">${label}</button>`).join('')}</div></div>`+content,'manage');
}
const manageInput=(name,label,value='',extra='')=>`<div class="field"><label for="manage-${name}">${E(label)}</label><input id="manage-${name}" name="${name}" value="${E(value)}" ${extra}></div>`;
const manageSelect=(name,label,options,value='')=>`<div class="field"><label for="manage-${name}">${E(label)}</label><select id="manage-${name}" name="${name}" required>${(value&&!options.some(([v])=>v===value)?[[value,value],...options]:options).map(([v,l])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
async function manageForm(table,id=''){
 adminData=await api('/admin');const old=id?adminData[table].find(r=>r.id===id):null;if(id&&!old)throw new Error('Record no longer exists. Refresh the workspace.');let fields='',title='';
 const status=`<label class="check-row"><input name="active" type="checkbox" ${!old||old.active?'checked':''} ${table==='staff'&&id===state.user.id?'disabled':''}><span>${table==='staff'?'Account is active':'Active for new participation'}</span></label>`;
 if(table==='programs'){title=old?'Edit program':'Add program';const p=old||{name:'',description:'',category:'Mentoring',min_age:0,max_age:18,outcome_label:''},d=old?JSON.parse(old.details):{enrollment_mode:'app',attendance_rule:'consecutive_absences',languages:['English','Spanish','Haitian Creole'],access:'Guardian registration; contact staff for help.',capacity:'See group availability.',record_scope:'Program participation and coordination only; no clinical records.'};
 fields=manageInput('name','Program name',p.name,'required maxlength="120"')+manageSelect('category','Category',['Mentoring','Family counseling','Safety workshops','Mental health workshops','Community events'].map(v=>[v,v]),p.category)+`<div class="field full"><label for="manage-description">Description</label><textarea id="manage-description" name="description" required maxlength="3000">${E(p.description)}</textarea></div>`+manageInput('min_age','Minimum age',p.min_age,'type="number" min="0" max="18" required')+manageInput('max_age','Maximum age',p.max_age,'type="number" min="0" max="18" required')+manageInput('outcome_label','Non-clinical outcome measure',p.outcome_label,'required maxlength="300"')+manageSelect('enrollment_mode','Intake system',[['app','Register participation here'],['secure_system','Private intake in external secure system']],d.enrollment_mode)+manageSelect('attendance_rule','Attendance policy',[['consecutive_absences','Regular: two consecutive unexplained absences'],['optional','Optional event: no absence alerts'],['none','No attendance here (private intake only)']],d.attendance_rule)+`<div class="field full"><details><summary>Program profile details</summary><div class="form-grid">${['tagline','audience','format','schedule','lead','staffing','access','followup','capacity','record_scope'].map(key=>manageInput('detail_'+key,titleCase(key),d[key]||'', 'maxlength="2000"')).join('')}${['locations','languages','activities','measures'].map(key=>`<div class="field"><label for="manage-detail_${key}">${E(titleCase(key))} (one per line)</label><textarea id="manage-detail_${key}" name="detail_${key}">${E((d[key]||[]).join('\n'))}</textarea></div>`).join('')}</div></details></div>`;
 }else if(table==='groups'){title=old?'Edit group':'Add group';const g=old||{program_id:'',name:'',school:'',neighborhood:adminData.workspace.service_areas[0],weekday:'',time:'',capacity:20};fields=manageInput('name','Group name',g.name,'required maxlength="120"')+manageSelect('program_id','Program',adminData.programs.filter(p=>JSON.parse(p.details).enrollment_mode==='app').map(p=>[p.id,p.name]),g.program_id)+manageInput('school','School / venue',g.school,'required maxlength="150"')+manageSelect('neighborhood','Service area',adminData.workspace.service_areas.map(v=>[v,v]),g.neighborhood)+manageInput('weekday','Meeting day / schedule',g.weekday,'required maxlength="40"')+manageInput('time','Meeting time',g.time,'required maxlength="80"')+manageInput('capacity','Capacity',g.capacity,'type="number" min="1" max="100" required')+`<p class="small muted field full">A group with history keeps its program and venue. Create a new group for a move so earlier attendance retains its context.</p>`;
 }else if(table==='staff'){title=old?'Edit staff account':'Add staff account';const s=old||{name:'',email:'',role:'teacher'};fields=manageInput('name','Staff name',s.name,'required maxlength="120"')+manageInput('email','Sign-in email',s.email,'type="email" required maxlength="200" autocomplete="off"')+manageSelect('role','Role',[['teacher','Session leader / teacher'],['manager','Program manager']],s.role)+manageInput('password',old?'New password (optional)':'Initial password','','type="password" minlength="12" maxlength="200" autocomplete="new-password" '+(old?'':'required'))+`<fieldset class="field full" id="manage-staff-groups" ${s.role==='manager'?'hidden':''}><legend>Assigned attendance groups</legend>${adminData.groups.map(g=>`<label class="check-row"><input type="checkbox" name="group_ids" value="${g.id}" ${adminData.assignments.some(a=>a.staff_id===id&&a.group_id===g.id)?'checked':''}><span>${E(g.name)}</span></label>`).join('')}</fieldset><p class="small muted field full">Passwords need at least 12 characters. Share initial credentials privately; this prototype sends no invitation email. Changing a password, role or active status ends existing sessions. Reassign open family concerns before deactivating an owner.</p>`;
 }else{title=old?'Edit volunteer':'Add volunteer / mentor';const v=old||{name:'',email:'',role:'Mentor'},roles=[...new Set(['Mentor','Workshop facilitator','Event helper','Supply driver',v.role])];fields=manageInput('name','Volunteer name',v.name,'required maxlength="120"')+manageInput('email','Volunteer email',v.email,'type="email" required maxlength="200"')+manageSelect('role','Volunteer role',roles.map(v=>[v,v]),v.role)+`<fieldset class="field full"><legend>Languages spoken (select all that apply)</legend>${['English','Spanish','Haitian Creole'].map(language=>`<label class="check-row"><input type="checkbox" name="languages" value="${E(language)}" ${spokenLanguages(v).includes(language)?'checked':''}><span>${E(language)}</span></label>`).join('')}<label for="volunteer-other-languages">Other languages (comma-separated)</label><input id="volunteer-other-languages" name="other_languages" maxlength="1600" value="${E(spokenLanguages(v).filter(l=>!['English','Spanish','Haitian Creole'].includes(l)).join(', '))}"><p class="small muted">Record at least one language the person says they speak. Do not infer it from their name.</p></fieldset><p class="small muted field full">Mentors can be assigned in active mentoring programs from Volunteers → Mentor matches. Reassign active matches before archiving a mentor.</p>`;}
 showDialog(title,`<form id="manage-form" data-table="${table}" data-id="${E(id)}"><input type="hidden" name="version" value="${old?.version??0}"><div class="form-grid">${fields}</div>${status}<div class="form-actions"><button class="btn primary" type="submit">Save ${table==='staff'?'account':table==='programs'?'program':table==='groups'?'group':'volunteer'}</button></div></form>`);
}
async function saveManagedRecord(form){const data=Object.fromEntries(new FormData(form)),table=form.dataset.table,payload={...data,version:Number(data.version),active:form.querySelector('[name=active]').checked};if(table==='volunteers'){payload.languages=[...new FormData(form).getAll('languages'),...data.other_languages.split(',').map(v=>v.trim()).filter(Boolean)];delete payload.other_languages;if(!payload.languages.length)throw new Error('Select or enter at least one spoken language.');}if(table==='staff'){payload.role=form.querySelector('[name=role]').value;payload.group_ids=new FormData(form).getAll('group_ids');}if(table==='programs'){payload.min_age=Number(data.min_age);payload.max_age=Number(data.max_age);payload.details={};for(const [key,value] of Object.entries(data))if(key.startsWith('detail_'))payload.details[key.slice(7)]=['locations','languages','activities','measures'].includes(key.slice(7))?value.split('\n').map(v=>v.trim()).filter(Boolean):value;}if(table==='groups')payload.capacity=Number(data.capacity);const id=form.dataset.id;if(id)await put('/admin/'+table+'/'+encodeURIComponent(id),payload);else await post('/admin/'+table,payload);dialog.close();await refresh(false);await manageWorkspace();notify('Saved. Existing history has been retained.');}
