function renderOffline(){app.innerHTML=`<main class="content" id="main">${brand()}<h1>You’re offline.</h1><p>The app shell is available, but sign-in, attendance and record changes need a connection. No family records are cached on this device.</p><button class="btn primary" data-action="retry-connection">Try again</button></main>`;}
