async function installApp(){if(matchMedia('(display-mode: standalone)').matches||navigator.standalone){notify('TidePath is already running as an installed app.');return;}if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return;}showDialog('Install TidePath',`<p>Install the app from this deployed HTTPS website to open it from your home screen or desktop.</p><ul><li><strong>iPhone / iPad:</strong> in Safari, use Share → Add to Home Screen.</li><li><strong>Android:</strong> in Chrome, use the browser menu → Install app or Add to Home Screen.</li><li><strong>Desktop:</strong> use the browser’s install icon or Install app menu.</li></ul><p>Attendance still requires connectivity. The app caches its shell, not family records or unsent attendance.</p>`);}

